def clean_html_text(html: str) -> str:
    text = re.sub(r"<script\b.*?</script>", " ", html, flags=re.I | re.S)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.I | re.S)
    text = re.sub(r"<[^>]+>", " ", text)
    text = text.replace("&nbsp;", " ").replace("&ndash;", "-").replace("&mdash;", "-")
    return re.sub(r"\s+", " ", text)


def rolling_sum(values: list[float], window: int) -> float:
    if len(values) <= window:
        return round(sum(values), 3)
    return round(max(sum(values[index : index + window]) for index in range(len(values) - window + 1)), 3)


def longest_wet_run(values: list[float], threshold: float = 0.1) -> int:
    best = current = 0
    for value in values:
        if value >= threshold:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def osm_counts(osm: dict[str, Any]) -> dict[str, int]:
    counts = {
        "elements": 0,
        "highway_features": 0,
        "major_road_features": 0,
        "destroyed_highway_features": 0,
        "bridge_features": 0,
        "amenity_features": 0,
        "school_features": 0,
        "police_features": 0,
        "waterway_features": 0,
        "storm_damage_text_mentions": 0,
    }
    major_roads = {"motorway", "trunk", "primary", "secondary"}
    for feature in osm.get("elements", []):
        counts["elements"] += 1
        tags = feature.get("tags") or {}
        highway = tags.get("highway")
        if highway:
            counts["highway_features"] += 1
        if highway in major_roads:
            counts["major_road_features"] += 1
        if "destroyed:highway" in tags:
            counts["destroyed_highway_features"] += 1
        if tags.get("bridge") in {"yes", "viaduct", "aqueduct"}:
            counts["bridge_features"] += 1
        if "amenity" in tags:
            counts["amenity_features"] += 1
        if tags.get("amenity") == "school":
            counts["school_features"] += 1
        if tags.get("amenity") == "police":
            counts["police_features"] += 1
        if "waterway" in tags:
            counts["waterway_features"] += 1
        joined_tags = " ".join(str(value).lower() for value in tags.values())
        if any(term in joined_tags for term in ["heavy rainfall", "storm daniel", "destroyed", "flood"]):
            counts["storm_damage_text_mentions"] += 1
    return counts


