def build_rainfall_metrics(
    openmeteo: dict[str, Any],
    power: dict[str, Any],
    era5: dict[str, Any],
    gpm: dict[str, Any],
    chirps: dict[str, Any],
) -> dict[str, float | int]:
    precip = [float(value) for value in openmeteo["hourly"]["precipitation"]]
    power_values = [float(value) for _, value in sorted(power["properties"]["parameter"]["PRECTOTCORR"].items())]
    gpm_stats = gpm["stats"]
    era5_stats = era5["stats"]
    chirps_stats = chirps["stats"]

    rainfall: dict[str, float | int] = {
        "local_hourly_total_mm": round(sum(precip), 1),
        "local_wettest_1h_mm": round(max(precip), 1),
        "local_wettest_6h_mm": rolling_sum(precip, 6),
        "local_wettest_24h_mm": rolling_sum(precip, 24),
        "local_wet_hours_ge_0p1mm": sum(1 for value in precip if value >= 0.1),
        "local_longest_wet_run_hours": longest_wet_run(precip),
        "local_hourly_record_hours": len(precip),
        "independent_daily_total_mm": round(sum(power_values), 2),
        "independent_wettest_day_mm": round(max(power_values), 2),
        "regional_gridded_mean_mm": round(gpm_stats["gpm_event_precip_mm_mean"], 2),
        "regional_gridded_max_mm": round(gpm_stats["gpm_event_precip_mm_max"], 2),
        "reanalysis_mean_mm": round(era5_stats["precipitation_sum_mm_mean"], 2),
        "reanalysis_max_mm": round(era5_stats["precipitation_sum_mm_max"], 2),
        "contrasting_gridded_mean_mm": round(chirps_stats["chirps_event_precip_mm_mean"], 2),
        "contrasting_gridded_max_mm": round(chirps_stats["chirps_event_precip_mm_max"], 2),
    }
    rainfall["regional_to_contrasting_max_ratio"] = round(
        rainfall["regional_gridded_max_mm"] / max(rainfall["contrasting_gridded_max_mm"], 0.001), 2
    )
    rainfall["regional_to_reanalysis_mean_ratio"] = round(
        rainfall["regional_gridded_mean_mm"] / rainfall["reanalysis_mean_mm"], 2
    )
    return rainfall


