        },
        "wadi_dam_exposure_coupling": {
            "long_narrow_wadi_reported": facts["nasa_long_narrow_wadi"],
            "two_dams_collapsed": reported_two_dams_collapsed,
            "second_dam_distance_km": facts["nasa_second_dam_distance_km"],
            "linear_infrastructure_marker_count": linear_marker_count,
