            "computed_value": derived_metrics["rainfall_persistence"],
            "threshold_or_test": "24h share near-total, 6h share above one-half, wet-run share above 0.9",
            "result": "local rainfall was concentrated and persistent enough to support a rainfall trigger",
        },
        {
