            },
            "threshold_or_test": "routing and dam facts true, with nonzero linear infrastructure and population context",
            "result": "the confined wadi, nearby second dam, and exposed infrastructure context support a routed flood-wave pathway",
        },
        {
            "row_id": "remote_disturbance_context",
            "formula": "radar pre/post counts and post-minus-pre VV mean; annual embedding change maximum",
            "computed_value": derived_metrics["remote_disturbance_context"],
            "threshold_or_test": "surface-change context may support disturbance but cannot replace the hydraulic consistency check",
            "result": "remote metrics are supporting context only",
        },
    ]
    return derived_metrics, derivation_ledger


def build_gt() -> dict[str, Any]:
    event = load_json("metadata/event.json")
    anchor = load_json("data/event_reports/event_reports_003_Locked_event_anchor_Storm_Daniel_Derna_flood.json")
    gdacs = load_json("data/event_catalogs/event_catalogs_001_GDACS_event_list_GeoJSON_API.json")
    openmeteo = load_json("data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json")
    power = load_json("data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json")
    era5 = load_json("data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json")
    gpm = load_json("data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = load_json("data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json")
    worldpop = load_json("data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json")
    osm = load_openstreetmap()
    alpha = load_json("data/remote_sensing/remote_sensing_004_Google_Satellite_Embedding_annual_cosine-change_stats.json")
    sentinel = load_json("data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json")

    rainfall = build_rainfall_metrics(openmeteo, power, era5, gpm, chirps)
    facts = report_facts()
    osm_metric = osm_counts(osm)
    exposed_population = float(worldpop["population_sum"]["population"])
    remote_sensing = build_remote_metrics(alpha, sentinel)
    derived_metrics, derivation_ledger = build_derivations(
        rainfall, facts, osm_metric, exposed_population, remote_sensing
    )

    gdacs_libya = None
    for feature in gdacs.get("features", []):
        props = feature.get("properties", {})
        if props.get("eventtype") == "FL" and props.get("iso3") == "LBY":
            gdacs_libya = props
            break

    primary_gt = {
        "target_family": TARGET_FAMILY,
        "derivation_ledger": derivation_ledger,
        "rejected_overreads": REJECTED_OVERREADS,
        "final_consistency_label": FINAL_LABEL,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": TARGET_FAMILY,
        "primary_gt": primary_gt,
        "event": {
            "package_id": event["package_id"],
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": f"{anchor['temporal_window']['start_date']} to {anchor['temporal_window']['end_date']}",
        },
        "key_values": {
            "rainfall": rainfall,
            "reported": {
                "wmo_rainfall_range_mm": facts["wmo_rainfall_range_mm"],
                "wmo_al_bayda_daily_record_mm": facts["wmo_al_bayda_daily_record_mm"],
                "two_dams_collapsed": bool(facts["wmo_two_dams_collapsed"] and facts["nasa_two_dams_collapsed"]),
                "long_narrow_wadi": facts["nasa_long_narrow_wadi"],
                "second_dam_distance_km": facts["nasa_second_dam_distance_km"],
                "flood_wave_height_m_range": facts["nasa_flood_wave_height_m_range"],
                "derna_population_context": facts["nasa_derna_population_context"],
            },
            "exposure_context": {
                "exposed_population": round(exposed_population, 2),
                "linear_features": osm_metric,
            },
            "remote_sensing": remote_sensing,
        },
        "derived_metrics": derived_metrics,
        "derivation_ledger": derivation_ledger,
        "rejected_overreads": REJECTED_OVERREADS,
        "supporting_metrics": {
            "catalog_context": {
                "red_flood_alert": bool(gdacs_libya and gdacs_libya.get("alertlevel") == "Red"),
                "country": gdacs_libya.get("country") if gdacs_libya else None,
                "window_start": gdacs_libya.get("fromdate") if gdacs_libya else None,
                "window_end": gdacs_libya.get("todate") if gdacs_libya else None,
            },
            "not_estimated_from_this_ledger": [
                "exact breach time of each dam",
                "dam outflow hydrograph or flood-wave velocity",
                "parcel-level flood depth",
                "casualty attribution",
                "final death toll",
                "building-by-building structural loss",
            ],
        },
        "rubric": RUBRIC,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    output = build_gt()
    out_path = Path(__file__).with_name("computed_gt.json")
    apply_deepened_task_frame(output)
    out_path.write_text(json.dumps(output, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
